function rpu(){const m=$('rpm'),s=$('rps');if(!m)return;const R=RT[RP.v],pts=Array.from({length:121},(_,i)=>at(R,i/120)),la=pts.map(p=>p[0]),lo=pts.map(p=>p[1]),a=Math.min(...la),b=Math.max(...la),c=Math.min(...lo),d=Math.max(...lo),p=at(R,RP.f);m.setAttribute('cx',30+(p[1]-c)/Math.max(d-c,.01)*700);m.setAttribute('cy',330-(p[0]-a)/Math.max(b-a,.01)*300);s.value=Math.round(RP.f*1000);$('rpt').textContent=fa(Math.round(RP.f*100))+'٪'}
